'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { GraduationCap } from 'lucide-react';

export default function MyMarksPage() {
    const [marks, setMarks] = useState<any[]>([]);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any[]>('/api/student/marks');
                if (res.success) setMarks(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                My Marks
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>
                View your internal marks (visible only after admin lock)
            </p>

            {marks.length === 0 ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <GraduationCap size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>No locked marks available yet. Marks become visible after admin approval and lock.</p>
                </div>
            ) : (
                <div className="table-container">
                    <table>
                        <thead><tr><th>Subject</th><th>Marks</th><th>Max Marks</th><th>Percentage</th><th>Status</th></tr></thead>
                        <tbody>
                            {marks.map((m) => (
                                <tr key={m.id}>
                                    <td style={{ fontWeight: 600 }}>{m.subject_id}</td>
                                    <td style={{ fontWeight: 700, fontSize: 16 }}>{m.marks}</td>
                                    <td>{m.max_marks}</td>
                                    <td>{m.marks && m.max_marks ? `${((m.marks / m.max_marks) * 100).toFixed(1)}%` : '—'}</td>
                                    <td><span className="badge badge-success">{m.status}</span></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}
